def fruit_distribution(s, n):
    apples_count = 0
    oranges_count = 0

    parts = s.split(" and ")
    for part in parts:
        if "apples" in part:
            apples_count = int(part.split()[0])
        elif "oranges" in part:
            oranges_count = int(part.split()[0])

    return n - apples_count - oranges_count

